--
-- Table structure for table `restaurant`
--

DROP TABLE IF EXISTS `restaurant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `restaurant` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '店铺名称',
  `emoji` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '图标',
  `rating` decimal(2,1) DEFAULT '0.0' COMMENT '评分',
  `distance` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '距离文案',
  `cat` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '叶子分类名称',
  `category_id` bigint DEFAULT '0' COMMENT '所属分类id（分级搜索用）',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '简介（前端字段 desc）',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '标签，逗号分隔',
  `sort` int DEFAULT '0' COMMENT '排序权重',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `min_order` decimal(8,2) DEFAULT '20.00' COMMENT '起送价',
  `delivery_fee` decimal(8,2) DEFAULT '0.00' COMMENT '配送费',
  `eta` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '预估送达时间',
  `open_status` tinyint DEFAULT '1' COMMENT '营业状态：1=营业中 0=已打烊',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_cat` (`cat`) USING BTREE,
  KEY `idx_rest_category` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='店铺表';
/*!40101 SET character_set_client = @saved_cs_client */;

