INSERT INTO `review` VALUES (1,1,'爱吃的小鹿',5,'招牌牛肉面汤头绝了，手工面筋道，辣油香而不燥，会回购！','刚刚','2026-10-23 16:31:59'),(2,1,'深夜食堂老板',4,'红油抄手皮薄馅大，就是上菜稍慢，胜在新鲜。','3天前','2026-10-23 16:31:59'),(3,1,'减肥失败者阿强',5,'酸辣肥肠面分量足又实惠，肥肠处理得干净，强烈推荐。','1周前','2026-10-23 16:31:59'),(4,1,'吃货老张',3,'卤香豆干中规中矩，可能我没点招牌面才是正解。','2周前','2026-10-23 16:31:59'),(5,1,'甜筒少女',5,'冰镇酸梅汤解辣一绝，店员还送了小菜，态度超好～','昨天','2026-10-23 16:31:59'),(6,2,'随便点点',4,'鸡胸蔬菜沙拉酱是油醋汁，吃着没负担，朋友聚餐也合适。','刚刚','2026-10-23 16:31:59'),(7,2,'干饭不积极',5,'牛油果鸡蛋三明治给得慷慨，全麦面包夹现切牛油果，满足。','3天前','2026-10-23 16:31:59'),(8,2,'麻辣星人',5,'藜麦时蔬碗饱腹感强，减脂期也能吃得开心。','1周前','2026-10-23 16:31:59'),(9,2,'元气满满酱',5,'烤时蔬卷清爽不油腻，配鲜榨羽衣甘蓝汁刚刚好。','2周前','2026-10-23 16:31:59'),(10,2,'一勺辣油',4,'鲜榨羽衣甘蓝汁微苦回甘，健身人士会喜欢。','昨天','2026-10-23 16:31:59'),(11,3,'佛系吃客',5,'现烤舒芙蕾端上来还在抖，入口即化太治愈了。','刚刚','2026-10-23 16:31:59'),(12,3,'深夜放毒王',5,'海盐提拉米苏酒香恰到好处，甜而不齁。','3天前','2026-10-23 16:31:59'),(13,3,'碳水教父',4,'莓果千层奶油不腻，夹着鲜莓酸得清醒。','1周前','2026-10-23 16:31:59'),(14,3,'露营美食家',4,'焦糖布丁壳脆心滑，甜度拿捏得刚好。','2周前','2026-10-23 16:31:59'),(15,3,'减脂期的小美',5,'芋泥啵啵杯料足，手捣芋泥配Q弹啵啵，罪恶感清零～','昨天','2026-10-23 16:31:59'),(16,4,'隔壁王叔叔',5,'深烘手冲单品风味干净带果酸，配落地窗发呆绝配。','刚刚','2026-10-23 16:31:59'),(17,4,'奶盖收集者',5,'生椰拿铁椰味浓又顺滑，每天续命就靠它。','3天前','2026-10-23 16:31:59'),(18,4,'炸鸡品鉴师',4,'桂花乌龙拿铁尾韵悠长，没想到咖啡还能这么清新。','1周前','2026-10-23 16:31:59'),(19,4,'慢生活阿May',5,'气泡美式清爽，醇厚咖啡配气泡刚刚好。','2周前','2026-10-23 16:31:59'),(20,4,'重口味小李',5,'脏脏可可可可碎配奶盖，罪恶但满足，值。','昨天','2026-10-23 16:31:59'),(21,5,'甜品研究员',4,'麻辣牛油锅底越煮越香，毛肚黄喉必点。','刚刚','2026-10-23 16:31:59'),(22,5,'早起一杯咖',4,'鲜切黄喉脆嫩弹牙，七上八下刚刚好。','3天前','2026-10-23 16:31:59'),(23,5,'火锅涮一切',5,'手打虾滑现打就是不一样，弹到弹牙。','1周前','2026-10-23 16:31:59'),(24,5,'水逆退散君',5,'现炸酥肉外酥里嫩，直接吃也香，强推。','2周前','2026-10-23 16:31:59'),(25,5,'光盘行动派',5,'红糖糍粑软糯裹黄豆粉，甜口收尾太满足了。','昨天','2026-10-23 16:31:59'),(26,6,'吃面不吐面',4,'韩式雪花炸鸡外皮酥到掉渣，甜辣酱腌得入味。','刚刚','2026-10-23 16:31:59'),(27,6,'三杯不过岗',5,'安格斯牛肉堡肉饼多汁，一口爆汁超满足。','3天前','2026-10-23 16:31:59'),(28,6,'轻食猎人',5,'黄金薯条现炸金黄外脆内软，停不下来。','1周前','2026-10-23 16:31:59'),(29,6,'云吞星人',5,'芝士薯泥拉丝绵密，配炸鸡绝了。','2周前','2026-10-23 16:31:59'),(30,6,'